15	
16	AivTempAllReduceMesh1DOneShot::AivTempAllReduceMesh1DOneShot(
17	    const OpParam& param, const u32 rankId, // 传通信域的rankId，userRank
18	    const std::vector<std::vector<u32>>& subCommRanks)
19	    : AivAlgTemplateBase(param, rankId, subCommRanks)
20	{}
