23	
24	std::vector<CostModelParam> AivTempAllReduceMesh1DOneShot::CalcCostCoeff(CalcCostCoeffParam param)
25	{
26	    int portNum = (param.netType == AlgNetType::CLOS) ? 8 : 1;
27	    int taskNum = 5;
28	    float A = 0.0f;
29	    float B = 0.0f;
30	    float C = 0.0f;
31	
32	    // 同时有localreduce和localcopy，所以需要调用两个接口获取两个步骤的B并相加
33	    float B1 = 0.0f;
34	    float B2 = 0.0f;
35	    CostModelManager::Global()->CalcMeshParam(1, param.netType, portNum, param.rankSize, A);
36	    if (param.needLocalCopy) {
37	        CostModelManager::Global()->CalcLocalCopyParams(1, EngineType::AICPU, B1);
38	    } else {
39	        B1 = 0.0f;
40	    }
41	    CostModelManager::Global()->CalcLocalReduceParams(param.rankSize - 1, EngineType::AICPU, B2);
42	    B = B1 + B2;
43	    CostModelManager::Global()->CalcLatencyParams(taskNum, EngineType::AIV, C);
44	
45	    std::vector<CostModelParam> params;
46	    params.push_back({A, B, C});
47	    HCCL_DEBUG("[%s] CalcCostCoeff A=%f B=%f C=%f.", __func__, A, B, C);
48	    return params;
49	}
50	
51	u64 AivTempAllReduceMesh1DOneShot::CalcScratchMultiple(BufferType inBuffType, BufferType outBuffType)
52	{
53	    (void)inBuffType;
54	    (void)outBuffType;
55	    u64 scratchMultiple = tempRankSize_;
56	    return scratchMultiple;
57	}
58	
59	HcclResult AivTempAllReduceMesh1DOneShot::CalcRes(
60	    HcclComm comm, const OpParam& param, const TopoInfoWithNetLayerDetails* topoInfo,
61	    AlgResourceRequest& resourceRequest)
62	{
63	    u32 threadNum = 1;
64	    resourceRequest.slaveThreadNum = threadNum - 1;
65	    for (u32 index = 0; index < threadNum - 1; index++) {
66	        resourceRequest.notifyNumPerThread.push_back(1);
67	    }
68	    resourceRequest.notifyNumOnMainThread = threadNum - 1;
69	
70	    std::vector<HcclChannelDesc> level0Channels;
71	    if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS && !topoInfo->level0PcieMix) {
72	        std::vector<HcclChannelDesc> myChannelDescs;
73	        CHK_RET(CalcChannelRequestMeshClosMultiJetty(comm, param, topoInfo, subCommRanks_, myChannelDescs, true));
74	        for (auto channel : myChannelDescs) {
75	            if (channel.channelProtocol == COMM_PROTOCOL_UB_MEM) {
76	                level0Channels.push_back(channel);
77	            }
78	        }
79	        HCCL_DEBUG("[AivTempAllReduceMesh1DOneShot::CalcRes] Get Channel Success!");
80	    } else {
81	        CHK_RET(CalcChannelRequestMesh1D(comm, param, topoInfo, subCommRanks_, level0Channels));
82	    }
83	    resourceRequest.channels.push_back(level0Channels);
84	    HCCL_WARNING("Resource calculation is temporarily not performed in the template.");
85	    return HCCL_SUCCESS;
86	}
87	
88	HcclResult AivTempAllReduceMesh1DOneShot::CalNumBlocks(u32& numBlocks, u64 dataSize, u32 numBlocksLimit)
89	{
90	    (void)dataSize;
91	    if (numBlocksLimit >= (tempRankSize_ + 1)) {
92	        numBlocks = tempRankSize_ + 1;
93	    } else {
94	        // 如果要用更少的核心可以在这里折算，比如rankSize/2个核心
95	        numBlocks = numBlocksLimit;
96	    }
97	    HCCL_INFO("[AivTempAllReduceMesh1DOneShot] Actually use core num[%u]", numBlocks);
98	    return HcclResult::HCCL_SUCCESS;
99	}
100	
101	HcclResult AivTempAllReduceMesh1DOneShot::KernelRun(
