    HCCL_INFO(
        "[%s] aiv cache hits, ctxTag[%s], keyHash[%llu], insCount[%u], algName[%s]", __func__, ctxTag.c_str(),
        header->keyHash, insCount, algName.c_str());
    cacheHit = true;
    return HCCL_SUCCESS;
}

