            &opArgs.extraArgs};
        CHK_RET(ExecuteKernelLaunchInner(opArgs, &aivExtraKernelArgs, sizeof(aivExtraKernelArgs)));
    } else {
        AivKernelArgs aivKernelArgs{
            opArgs.buffersIn,
            opArgs.input,
